// Road 455 pinch: buildings 2224/2225 (rotated OSM quads) leave only a ~2.5 m diagonal gap on the
// alley line, and the routed lane passes 0.71 m from 2224's edge and 1.17 m from 2225's - inside the
// 1.7 m car hull. Fine pose probe found zero hull-free poses. Minimal faithful trim: move ONLY the
// two alley-facing edges inward along their own inward normals (2224 by 1.2 m, 2225 by 0.6 m),
// opening a ~4.3 m alley with >=1.9 m lane-to-face clearance both sides. All other faces, heights
// and every other building are untouched. Sig = first footprint vertex (unique), edge = vertex
// indices of the alley-facing edge, d = inward shift in metres.
export const BLDG_FIX = [
  { sig: [-447.7, 194.2], edge: [2, 3], d: 1.2 },
  { sig: [-440.9, 208.3], edge: [0, 1], d: 0.6 },
  { sig: [-368.9, 204.2], edge: [0, 1], d: 0.8 },
  // Appareddy Palya Road bend: building corner (-514.4,221.3) ate ~2.3m into the 6.6m
  // carriageway on the inside of the northwest bend; auto beached against it (coverage idx 43).
  { sig: [-525.1, 217.6], edge: [1, 2], d: 2.6 },
];
export function applyBldgFix(buildings) {
  for (const f of BLDG_FIX) {
    const b = buildings.find(b => b.p && Math.hypot(b.p[0][0] - f.sig[0], b.p[0][1] - f.sig[1]) < 0.05);
    if (!b) { console.warn('BLDG_FIX: no building at', f.sig); continue; }
    const n = b.p.length;
    const closed = b.p[0][0] === b.p[n - 1][0] && b.p[0][1] === b.p[n - 1][1];
    const [i, j] = f.edge, a = b.p[i], c = b.p[j];
    let cx = 0, cz = 0; const m = closed ? n - 1 : n;
    for (let k = 0; k < m; k++) { cx += b.p[k][0]; cz += b.p[k][1]; }
    cx /= m; cz /= m;
    const ex = c[0] - a[0], ez = c[1] - a[1], L = Math.hypot(ex, ez);
    let nx = -ez / L, nz = ex / L;
    const mx = (a[0] + c[0]) / 2, mz = (a[1] + c[1]) / 2;
    if ((cx - mx) * nx + (cz - mz) * nz < 0) { nx = -nx; nz = -nz; }
    a[0] += nx * f.d; a[1] += nz * f.d; c[0] += nx * f.d; c[1] += nz * f.d;
    if (closed) { b.p[n - 1][0] = b.p[0][0]; b.p[n - 1][1] = b.p[0][1]; }
  }
}
